options.postprocess_expression:
${
                                    if (!inputs || !inputs.data) {
                                        return [];
                                    }
                                    var skip = ["pro", "codex", "chat", "audio", "image", "instruct", "turbo"];
                                    var models = inputs.data.filter(function (m) {
                                        var match = /^openai\/gpt-[0-9][0-9.]*o?(?:-([a-z]+))?$/.exec(m.id);
                                        return match !== null && skip.indexOf(match[1]) === -1;
                                    });
                                    models.sort(function (a, b) {
                                        return b.created - a.created;
                                    });
                                    return models.map(function (m) {
                                        var id = m.id.slice("openai/".length);
                                        var inputs = (m.architecture && m.architecture.input_modalities) || [];
                                        var note = inputs.indexOf("image") === -1 ? ", text only" : "";
                                        return [m.name.replace(/^OpenAI: /, "") + " (" + id + ")" + note, id];
                                    });
                                }

